<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientAllowedScopesM2mAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientAllowedScopesM2mAccessor trait.
 *
 * Covers null default, string/VO assignment via withAllowedScopesM2m,
 * getAllowedScopesM2m/allowedScopesM2m accessors, and isAllowedScopesM2mChanged with/without original.
 */
class TrustedClientAllowedScopesM2mAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAllowedScopesM2m creates a new instance with the AllowedScopesM2m set
     * from a string value, and getAllowedScopesM2m returns the primitive string.
     */
    public function testWithAllowedScopesM2mFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedScopesM2mAccessorUnitTest();

        // Act
        $result = $holder->withAllowedScopesM2m('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getAllowedScopesM2m());
    }
    /**
     * Asserts that withallowedScopesM2m has access to the value object
     * from a string value, and getAllowedScopesM2m returns the primitive string.
     */
    public function testWithAllowedScopesM2mFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedScopesM2mAccessorUnitTest();

        // Act
        $result = $holder->withAllowedScopesM2m('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->allowedScopesM2m()->value());
    }
    public function testChangedAllowedScopesM2m(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedScopesM2mAccessorUnitTest();
        $original = $holder->withAllowedScopesM2m('one');
        $same = $holder->withAllowedScopesM2m('one');
        $modified = $holder->withAllowedScopesM2m('other');

        // Act
        $unchanged = $holder->isAllowedScopesM2mChanged();
        $withSame = $original->isAllowedScopesM2mChanged($same);
        $withDiferent = $original->isAllowedScopesM2mChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientAllowedScopesM2mAccessorUnitTest
{
    use TrustedClientAllowedScopesM2mAccessor;
}
